HOUSES = range(5)
FIRST, MIDDLE = 0, 2


def _right_of(a, b):
    return a == b + 1


def _next_to(a, b):
    return abs(a - b) == 1


def _solve():
    for red, green, ivory, yellow, blue in permutations(HOUSES):
        if not _right_of(green, ivory):
            continue
        for english, spaniard, ukrainian, norwegian, japanese in permutations(HOUSES):
            if english != red or norwegian != FIRST or not _next_to(norwegian, blue):
                continue
            for coffee, tea, milk, orange_juice, water in permutations(HOUSES):
                if coffee != green or ukrainian != tea or milk != MIDDLE:
                    continue
                for dancing, painting, reading, football, chess in permutations(HOUSES):
                    if (painting != yellow or football != orange_juice
                            or japanese != chess):
                        continue
                    for dog, snail, fox, horse, zebra in permutations(HOUSES):
                        if (spaniard != dog or snail != dancing
                                or not _next_to(reading, fox)
                                or not _next_to(painting, horse)):
                            continue
                        names = {
                            english: 'Englishman',
                            spaniard: 'Spaniard',
                            ukrainian: 'Ukrainian',
                            norwegian: 'Norwegian',
                            japanese: 'Japanese',
                        }
                        return names[water], names[zebra]
    return None


_SOLUTION = _solve()


def drinks_water():
    return _SOLUTION[0]


def owns_zebra():
    return _SOLUTION[1]
